<script>export let data;let showAnswers=false;</script>
<div class="page-head"><div class="eyebrow">INSTRUCTOR ONLY / CONTROL TERMINAL</div><h1>Exam <span class="gradient-text">operations.</span></h1><p class="subline">Instructor-only metrics and the private question bank. Never share credentials with students.</p></div>
<div class="grid3"><div class="panel"><div class="stat-label">REGISTERED STUDENTS</div><p class="big-num">{data.stats.students}</p></div><div class="panel"><div class="stat-label">COMPLETED EXAMS</div><p class="big-num">{data.stats.completed}</p></div><div class="panel"><div class="stat-label">PASS RATE</div><p class="big-num">{data.stats.passRate}%</p></div></div>
<section class="panel" style="margin-top:20px"><div class="flex between"><h2 class="section-title">Protected question bank</h2><span class="tag">{data.totalBank} ITEMS</span></div><p class="notice">The answer key is returned only to an authenticated instructor, never to student pages. Some original reading questions were reconstructed from photographs and are flagged for editorial review.</p><div class="flex between" style="margin:22px 0"><span class="muted tiny">Page {data.page+1} / 30</span><button class="btn sm secondary" onclick={()=>showAnswers=!showAnswers}>{showAnswers?'Hide answer key':'Reveal answer key'}</button></div>
 <div class="stack">{#each data.questions as q}<div class="item"><div class="flex between"><span class="stat-label">{q.id} · {q.category}</span>{#if q.needsInstructorReview}<span class="warningtext tiny">PHOTO REVIEW</span>{/if}</div><p><strong>{q.prompt}</strong></p><div class="grid2 answer-grid">{#each q.options as o,i}<span class:correct={showAnswers && 'ABCD'[i]===q.correct}>{'ABCD'[i]}. {o}</span>{/each}</div></div>{/each}</div>
 <div class="flex between" style="margin-top:22px"><a aria-disabled={data.page===0} class="btn sm secondary" href={'/admin?page='+Math.max(0,data.page-1)}>← Previous</a><a class="btn sm primary" href={'/admin?page='+Math.min(29,data.page+1)}>Next →</a></div>
</section>
<section class="panel" style="margin-top:20px"><h2 class="section-title">Recent student results</h2><table class="table"><thead><tr><th>STUDENT</th><th>EMAIL (PRIVATE)</th><th>SCORE</th><th>DATE</th></tr></thead><tbody>{#each data.stats.recent as r}<tr><td>{r.name}</td><td>{r.email}</td><td>{r.percent}%</td><td>{new Date(r.completed_at).toLocaleDateString()}</td></tr>{:else}<tr><td colspan="4">No results yet.</td></tr>{/each}</tbody></table></section>
<style>.item{border:1px solid #c4dcff25;border-radius:14px;padding:18px}.item p{font-size:14px;line-height:1.55}.answer-grid{gap:6px 20px;font-size:12px;color:#a6b6cb}.answer-grid span.correct{color:#80f8cf;font-weight:bold}</style>
